import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Summing test.'});
const session = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'run tool', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 't1', name: 't1', input: {}}};

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

async function runSummingTest(rounds: MessageChunk[][]): Promise<UsageMetadata | undefined> {
  let finalUsage: UsageMetadata | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, usage) => {
      finalUsage = usage;
    },
  };

  const registry = new ToolRegistry();
  registry.register({name: 't1', description: 't1', inputSchema: {}}, async () => 'done');

  const orchestrator = createChatOrchestrator(scriptedProvider(rounds), promptBuilder, registry, {hooks});

  await orchestrator.processMessage(session());
  return finalUsage;
}

describe('chatOrchestrator usage summing', () => {
  it('sums usage across multiple rounds', async () => {
    // [validated by: reports the summed usage from every provider call in a turn with two tool rounds](../../specs/hal-engine-config-hooks/spec.md#L39)
    const finalUsage = await runSummingTest([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 5, totalTokens: 15}}],
      [
        {type: 'text', text: 'ok'},
        {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 10, totalTokens: 30}},
      ],
    ]);

    expect(finalUsage).toEqual({
      inputTokens: 30,
      outputTokens: 15,
      totalTokens: 45,
    });
  });

  it('preserves undefined when no rounds report usage', async () => {
    // [validated by: preserves undefined when no rounds report usage](../../specs/hal-engine-config-hooks/spec.md#L40)
    const finalUsage = await runSummingTest([
      [
        {type: 'text', text: 'ok'},
        {type: 'stop', stopReason: 'end_turn'},
      ],
    ]);

    expect(finalUsage).toBeUndefined();
  });

  it('counts reported rounds while skipping undefined ones', async () => {
    // [validated by: counts reported rounds while skipping undefined ones](../../specs/hal-engine-config-hooks/spec.md#L41)
    const finalUsage = await runSummingTest([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 5, totalTokens: 15}}],
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}], // No usage
      [
        {type: 'text', text: 'ok'},
        {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 10, totalTokens: 30}},
      ],
    ]);

    expect(finalUsage).toEqual({
      inputTokens: 30,
      outputTokens: 15,
      totalTokens: 45,
    });
  });
});

